-- Conventions
--   * Entity ids are UUIDv7, generated by the application (time-ordered, URL-safe).
--   * High-volume tables (pings, http_results, notifications) use bigint identity keys.
--   * Enum-like columns are text + CHECK so they can evolve with plain ALTERs.
--   * Tenant-owned tables carry org_id and expose UNIQUE (id, org_id) so child tables
--     can use composite FKs: the database itself refuses cross-org links.

-- ───────────────────────────── tenancy ─────────────────────────────

CREATE TABLE users (
    id            uuid PRIMARY KEY,
    email         text NOT NULL,
    password_hash text NOT NULL,
    created_at    timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX users_email_key ON users (lower(email));

CREATE TABLE orgs (
    id         uuid PRIMARY KEY,
    name       text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE memberships (
    user_id    uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    org_id     uuid NOT NULL REFERENCES orgs (id) ON DELETE CASCADE,
    role       text NOT NULL CHECK (role IN ('owner', 'admin', 'member')),
    created_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (user_id, org_id)
);
CREATE INDEX memberships_org_id_idx ON memberships (org_id);

CREATE TABLE projects (
    id         uuid PRIMARY KEY,
    org_id     uuid NOT NULL REFERENCES orgs (id) ON DELETE CASCADE,
    name       text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (id, org_id)
);
CREATE INDEX projects_org_id_idx ON projects (org_id);

-- ─────────────────────── heartbeat / webhook checks ───────────────────────

CREATE TABLE checks (
    id               uuid PRIMARY KEY,
    org_id           uuid NOT NULL REFERENCES orgs (id) ON DELETE CASCADE,
    project_id       uuid NOT NULL,
    kind             text NOT NULL CHECK (kind IN ('heartbeat', 'webhook')),
    name             text NOT NULL,
    token            text NOT NULL UNIQUE,
    schedule_kind    text NOT NULL CHECK (schedule_kind IN ('cron', 'period')),
    cron_expr        text,
    tz               text,
    period_secs      integer,
    grace_secs       integer NOT NULL DEFAULT 300 CHECK (grace_secs >= 0),
    -- How long a run may stay 'started' before it counts as hung. NULL = no limit.
    max_runtime_secs integer CHECK (max_runtime_secs > 0),
    status           text NOT NULL DEFAULT 'new'
                     CHECK (status IN ('new', 'up', 'started', 'down', 'paused')),
    last_ping_at     timestamptz,
    last_start_at    timestamptz,
    next_expected_at timestamptz,
    alert_after      timestamptz,
    created_at       timestamptz NOT NULL DEFAULT now(),
    updated_at       timestamptz NOT NULL DEFAULT now(),
    UNIQUE (id, org_id),
    FOREIGN KEY (project_id, org_id) REFERENCES projects (id, org_id) ON DELETE CASCADE,
    CHECK (
        (schedule_kind = 'cron'   AND cron_expr IS NOT NULL AND tz IS NOT NULL AND period_secs IS NULL)
     OR (schedule_kind = 'period' AND period_secs > 0 AND cron_expr IS NULL)
    )
);
CREATE INDEX checks_project_id_idx ON checks (project_id);
-- Scheduler hot path: overdue checks that can still flip to 'down'.
CREATE INDEX checks_alert_after_idx ON checks (alert_after) WHERE status IN ('up', 'started');

CREATE TABLE pings (
    id          bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    check_id    uuid NOT NULL REFERENCES checks (id) ON DELETE CASCADE,
    kind        text NOT NULL CHECK (kind IN ('start', 'success', 'fail', 'exit')),
    exit_code   integer,
    duration_ms integer,
    source_ip   inet,
    user_agent  text,
    body        text CHECK (octet_length(body) <= 10240),
    created_at  timestamptz NOT NULL DEFAULT now(),
    CHECK (kind <> 'exit' OR exit_code IS NOT NULL)
);
CREATE INDEX pings_check_id_created_at_idx ON pings (check_id, created_at DESC);
CREATE INDEX pings_created_at_brin ON pings USING brin (created_at);

-- ─────────────────────────── HTTP uptime ───────────────────────────

CREATE TABLE http_monitors (
    id                   uuid PRIMARY KEY,
    org_id               uuid NOT NULL REFERENCES orgs (id) ON DELETE CASCADE,
    project_id           uuid NOT NULL,
    name                 text NOT NULL,
    url                  text NOT NULL,
    method               text NOT NULL DEFAULT 'GET'
                         CHECK (method IN ('GET', 'HEAD', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS')),
    -- Request headers as JSON, encrypted with the app key (may contain Authorization).
    headers_enc          bytea,
    body                 text,
    interval_secs        integer NOT NULL DEFAULT 60 CHECK (interval_secs >= 30),
    timeout_ms           integer NOT NULL DEFAULT 10000 CHECK (timeout_ms BETWEEN 100 AND 60000),
    -- NULL means "any 2xx".
    expected_status      smallint CHECK (expected_status BETWEEN 100 AND 599),
    body_contains        text,
    fail_threshold       smallint NOT NULL DEFAULT 2 CHECK (fail_threshold >= 1),
    status               text NOT NULL DEFAULT 'new'
                         CHECK (status IN ('new', 'up', 'down', 'paused')),
    consecutive_failures integer NOT NULL DEFAULT 0,
    last_checked_at      timestamptz,
    next_run_at          timestamptz NOT NULL DEFAULT now(),
    created_at           timestamptz NOT NULL DEFAULT now(),
    updated_at           timestamptz NOT NULL DEFAULT now(),
    UNIQUE (id, org_id),
    FOREIGN KEY (project_id, org_id) REFERENCES projects (id, org_id) ON DELETE CASCADE
);
CREATE INDEX http_monitors_project_id_idx ON http_monitors (project_id);
-- Prober hot path.
CREATE INDEX http_monitors_next_run_at_idx ON http_monitors (next_run_at) WHERE status <> 'paused';

-- Raw probe results. Candidate for daily range partitioning once volume grows.
CREATE TABLE http_results (
    id          bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    monitor_id  uuid NOT NULL REFERENCES http_monitors (id) ON DELETE CASCADE,
    ok          boolean NOT NULL,
    status_code smallint,
    latency_ms  integer,
    error       text,
    created_at  timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX http_results_monitor_id_created_at_idx ON http_results (monitor_id, created_at DESC);
CREATE INDEX http_results_created_at_brin ON http_results USING brin (created_at);

CREATE TABLE http_rollups (
    monitor_id  uuid NOT NULL REFERENCES http_monitors (id) ON DELETE CASCADE,
    bucket_hour timestamptz NOT NULL,
    count       integer NOT NULL,
    fail_count  integer NOT NULL,
    avg_ms      integer,
    p50_ms      integer,
    p95_ms      integer,
    PRIMARY KEY (monitor_id, bucket_hour)
);

-- ───────────────────────────── incidents ─────────────────────────────

CREATE TABLE incidents (
    id            uuid PRIMARY KEY,
    org_id        uuid NOT NULL REFERENCES orgs (id) ON DELETE CASCADE,
    -- Exclusive arc: exactly one target. Composite FKs are skipped by Postgres
    -- when the target column is NULL (MATCH SIMPLE), so both can coexist.
    check_id      uuid,
    monitor_id    uuid,
    reason        text NOT NULL CHECK (reason IN ('missed', 'failed', 'hung', 'http_down')),
    detail        text,
    cause_ping_id bigint REFERENCES pings (id) ON DELETE SET NULL,
    started_at    timestamptz NOT NULL DEFAULT now(),
    resolved_at   timestamptz,
    FOREIGN KEY (check_id, org_id)   REFERENCES checks (id, org_id)        ON DELETE CASCADE,
    FOREIGN KEY (monitor_id, org_id) REFERENCES http_monitors (id, org_id) ON DELETE CASCADE,
    CHECK (num_nonnulls(check_id, monitor_id) = 1),
    CHECK (resolved_at IS NULL OR resolved_at >= started_at)
);
-- At most one open incident per target; makes the scheduler idempotent.
CREATE UNIQUE INDEX incidents_open_check_key   ON incidents (check_id)   WHERE resolved_at IS NULL;
CREATE UNIQUE INDEX incidents_open_monitor_key ON incidents (monitor_id) WHERE resolved_at IS NULL;
CREATE INDEX incidents_org_id_started_at_idx ON incidents (org_id, started_at DESC);
CREATE INDEX incidents_check_id_started_at_idx ON incidents (check_id, started_at DESC) WHERE check_id IS NOT NULL;
CREATE INDEX incidents_monitor_id_started_at_idx ON incidents (monitor_id, started_at DESC) WHERE monitor_id IS NOT NULL;
-- Lets retention deletes on pings find referencing incidents without a seq scan.
CREATE INDEX incidents_cause_ping_id_idx ON incidents (cause_ping_id) WHERE cause_ping_id IS NOT NULL;

-- ─────────────────────────── alert channels ───────────────────────────

CREATE TABLE channels (
    id          uuid PRIMARY KEY,
    org_id      uuid NOT NULL REFERENCES orgs (id) ON DELETE CASCADE,
    kind        text NOT NULL CHECK (kind IN ('email', 'slack', 'discord', 'webhook')),
    name        text NOT NULL,
    -- Kind-specific config as JSON (addresses, webhook URLs, secrets), encrypted with the app key.
    config_enc  bytea NOT NULL,
    verified_at timestamptz,
    created_at  timestamptz NOT NULL DEFAULT now(),
    UNIQUE (id, org_id)
);
CREATE INDEX channels_org_id_idx ON channels (org_id);

CREATE TABLE check_channels (
    check_id   uuid NOT NULL,
    channel_id uuid NOT NULL,
    org_id     uuid NOT NULL,
    PRIMARY KEY (check_id, channel_id),
    FOREIGN KEY (check_id, org_id)   REFERENCES checks (id, org_id)   ON DELETE CASCADE,
    FOREIGN KEY (channel_id, org_id) REFERENCES channels (id, org_id) ON DELETE CASCADE
);
CREATE INDEX check_channels_channel_id_idx ON check_channels (channel_id);

CREATE TABLE monitor_channels (
    monitor_id uuid NOT NULL,
    channel_id uuid NOT NULL,
    org_id     uuid NOT NULL,
    PRIMARY KEY (monitor_id, channel_id),
    FOREIGN KEY (monitor_id, org_id) REFERENCES http_monitors (id, org_id) ON DELETE CASCADE,
    FOREIGN KEY (channel_id, org_id) REFERENCES channels (id, org_id)      ON DELETE CASCADE
);
CREATE INDEX monitor_channels_channel_id_idx ON monitor_channels (channel_id);

-- Transactional outbox, drained by the notifier worker.
CREATE TABLE notifications (
    id              bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    incident_id     uuid NOT NULL REFERENCES incidents (id) ON DELETE CASCADE,
    channel_id      uuid NOT NULL REFERENCES channels (id) ON DELETE CASCADE,
    event           text NOT NULL CHECK (event IN ('down', 'up', 'fail')),
    -- Message snapshot rendered at enqueue time.
    payload         jsonb NOT NULL,
    status          text NOT NULL DEFAULT 'pending'
                    CHECK (status IN ('pending', 'sending', 'sent', 'dead')),
    attempts        integer NOT NULL DEFAULT 0,
    next_attempt_at timestamptz NOT NULL DEFAULT now(),
    last_error      text,
    created_at      timestamptz NOT NULL DEFAULT now(),
    sent_at         timestamptz,
    UNIQUE (incident_id, channel_id, event),
    CHECK ((status = 'sent') = (sent_at IS NOT NULL))
);
-- 'sending' rows are leased until next_attempt_at, so a crashed notifier's work gets reclaimed.
CREATE INDEX notifications_due_idx ON notifications (next_attempt_at) WHERE status IN ('pending', 'sending');
CREATE INDEX notifications_channel_id_idx ON notifications (channel_id);
